def gray(s): return s[0]+''.join(str(int(s[i])^int(s[i-1])) for i in range(1,len(s)))
for r,pairs in samples.items():
 for a,b in pairs:
  matches=[x for x in rots(a) if gray(x)==b]
  print(a,b,matches)

